const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '一元二次方程求根公式' },
      { kind: 'text', payload: '2x²' },
      { kind: 'text', payload: '+ 4x' },
      { kind: 'text', payload: '− 6' },
      { kind: 'text', payload: '= 0' },
      { kind: 'text', payload: 'a = 2' },
      { kind: 'text', payload: 'b = 4' },
      { kind: 'text', payload: 'c = −6' },
      { kind: 'text', payload: '求根公式' },
      { kind: 'text', payload: 'x = ( −b ± √(b² − 4ac) ) / (2a)' },
      { kind: 'text', payload: 'Δ = b² − 4ac = 64' },
      { kind: 'text', payload: '代入：Δ = 4² − 4·2·(−6) = 16 + 48 = 64' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W / 2;
    var titleY = H * 0.08;
    var eqY = H * 0.20;
    var calloutY = H * 0.34;
    var panelX = W * 0.09;
    var panelY = H * 0.48;
    var panelW = W * 0.82;
    var panelH = H * 0.30;
    var deltaY = H * 0.84;
    var computeY = H * 0.93;
    var eqA = cx - W * 0.14;
    var eqB = cx - W * 0.045;
    var eqC = cx + W * 0.05;
    var eqEnd = cx + W * 0.15;
    var boxW = W * 0.18;
    var boxH = H * 0.085;
    var calloutA = cx - W * 0.30;
    var calloutB = cx;
    var calloutC = cx + W * 0.30;

    function roundRect(x, y, w, h, r) {
      return [
        ['M', x + r, y],
        ['L', x + w - r, y],
        ['Q', x + w, y, x + w, y + r],
        ['L', x + w, y + h - r],
        ['Q', x + w, y + h, x + w - r, y + h],
        ['L', x + r, y + h],
        ['Q', x, y + h, x, y + h - r],
        ['L', x, y + r],
        ['Q', x, y, x + r, y],
        ['Z']
      ];
    }
    function line(x1, y1, x2, y2) {
      return [['M', x1, y1], ['L', x2, y2]];
    }
    var paths = [];
    var children = [];
    function addPath(id, commands, fill, stroke) {
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id, fill: fill };
      if (stroke) node.stroke = stroke;
      children.push(node);
    }
    function addLabel(i, x, y, h, v, color) {
      children.push({
        type: 'label',
        contentId: metrics[i].contentId,
        anchor: { x: x, y: y },
        hAlign: h,
        vAlign: v,
        color: color
      });
    }

    addPath('bg', roundRect(0, 0, W, H, 18), '#F7F9FC', null);
    addPath('titleRule', line(cx - W * 0.15, titleY + H * 0.045, cx + W * 0.15, titleY + H * 0.045), '#C9D6E3', { width: 2, cap: 'round' });

    addPath('barA', line(eqA - W * 0.055, eqY + H * 0.045, eqA + W * 0.055, eqY + H * 0.045), '#C0392B', { width: 5, cap: 'round' });
    addPath('barB', line(eqB - W * 0.045, eqY + H * 0.045, eqB + W * 0.045, eqY + H * 0.045), '#1F6FB2', { width: 5, cap: 'round' });
    addPath('barC', line(eqC - W * 0.045, eqY + H * 0.045, eqC + W * 0.045, eqY + H * 0.045), '#2E8B57', { width: 5, cap: 'round' });

    var leaderY0 = eqY + H * 0.045;
    var leaderY1 = calloutY - boxH / 2;
    addPath('leadA', line(eqA, leaderY0, calloutA, leaderY1), '#C0392B', { width: 2, cap: 'round', dash: [5, 5] });
    addPath('leadB', line(eqB, leaderY0, calloutB, leaderY1), '#1F6FB2', { width: 2, cap: 'round', dash: [5, 5] });
    addPath('leadC', line(eqC, leaderY0, calloutC, leaderY1), '#2E8B57', { width: 2, cap: 'round', dash: [5, 5] });

    addPath('dotA', visualSdk.circle(eqA, leaderY0, 4), '#C0392B', null);
    addPath('dotB', visualSdk.circle(eqB, leaderY0, 4), '#1F6FB2', null);
    addPath('dotC', visualSdk.circle(eqC, leaderY0, 4), '#2E8B57', null);

    function box(prefix, x, color, inner) {
      addPath(prefix + 'Outer', roundRect(x - boxW / 2, calloutY - boxH / 2, boxW, boxH, 12), color, null);
      addPath(prefix + 'Inner', roundRect(x - boxW / 2 + 2, calloutY - boxH / 2 + 2, boxW - 4, boxH - 4, 10), inner, null);
    }
    box('boxA', calloutA, '#C0392B', '#FFF2F0');
    box('boxB', calloutB, '#1F6FB2', '#EDF5FC');
    box('boxC', calloutC, '#2E8B57', '#EFF8F2');

    addPath('panelOuter', roundRect(panelX, panelY, panelW, panelH, 16), '#D5DEE8', null);
    addPath('panelInner', roundRect(panelX + 2, panelY + 2, panelW - 4, panelH - 4, 14), '#FFFFFF', null);

    addPath('deltaOuter', roundRect(cx - W * 0.22, deltaY - H * 0.045, W * 0.44, H * 0.09, 12), '#7B3FA0', null);
    addPath('deltaInner', roundRect(cx - W * 0.22 + 2, deltaY - H * 0.045 + 2, W * 0.44 - 4, H * 0.09 - 4, 10), '#F5EEFA', null);

    addLabel(0, cx, titleY, 'center', 'middle', '#26354A');
    addLabel(1, eqA, eqY, 'center', 'middle', '#C0392B');
    addLabel(2, eqB, eqY, 'center', 'middle', '#1F6FB2');
    addLabel(3, eqC, eqY, 'center', 'middle', '#2E8B57');
    addLabel(4, eqEnd, eqY, 'center', 'middle', '#26354A');
    addLabel(5, calloutA, calloutY, 'center', 'middle', '#C0392B');
    addLabel(6, calloutB, calloutY, 'center', 'middle', '#1F6FB2');
    addLabel(7, calloutC, calloutY, 'center', 'middle', '#2E8B57');
    addLabel(8, cx, panelY + panelH * 0.18, 'center', 'middle', '#5A6B7B');
    addLabel(9, cx, panelY + panelH * 0.50, 'center', 'middle', '#26354A');
    addLabel(10, cx, deltaY, 'center', 'middle', '#7B3FA0');
    addLabel(11, cx, computeY, 'center', 'middle', '#5A6B7B');

    return {
      schemaVersion: 1,
      sceneId: 'quadratic-formula-transcription',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
